const C=(id,label,description,tier='standard',axes=[])=>({id,label,description,tier,axes});
const V=(plate,title,subtitle,palette,framing,weather,tide,light,motion,focalObjects,characters,sensoryPriority,audio,proseMode)=>({plate,title,subtitle,palette,framing,weather,tide,light,motion,focalObjects,characters,sensoryPriority,audio,proseMode});
export const SCENE_ORDER=[
  ['smoke-before-daylight','Smoke Before Daylight'],
  ['the-drying-racks','The Drying Racks'],
  ['race-beneath-the-fish','Race Beneath the Fish'],
  ['the-eighth-hook','The Eighth Hook'],
  ['the-work-nobody-saw','The Work Nobody Saw'],
  ['season-close','When the Fire Burns Low']
];
export const BEATS={
's1-waking':{id:'s1-waking',sceneId:'smoke-before-daylight',kicker:'Age eight · before the household rises',title:'Smoke Before Daylight',pressure:'The household is waking. Work will soon be assigned.',body:`<p>Kalos woke because Pali had worked one cold foot out from under the blanket and planted it against his ribs.</p><p>The roof was gone above them, hidden by smoke. People remained: knees, shoulders, a sleeping mouth open to the dark. Seli was already dressing beside the banked fire, trying to leave before anyone could give her a younger child.</p><p>Near the coals, a strip of fish skin tightened and shone.</p>`,choicePrompt:'What draws him first?',choiceHint:'A small choice of attention. The household has already begun without him.',choices:[C('cover-pali','Pull the blanket back over Pali','Do it quietly enough that the younger child never wakes.','light'),C('follow-seli','Slip after Seli','Reach the fire before she can disappear into adult work.','light'),C('listen-still','Remain still and listen','The adults nearest the doorway think the children are asleep.','light')],freeText:true,visual:V('longhouse','Smoke Before Daylight','The Long Roof household wakes beneath its own smoke.','ember-smoke','wide','low-cloud','falling','banked coals beneath blue predawn',['smoke folding below the beams','sleeping bodies shifting'],['Pali’s blanket','crisp fish skin','Seli’s belt cord'],[['kalos','foreground-left','awake under a shared blanket','pali','near'],['pali','center','sleeping with one foot uncovered','away','near'],['seli','background-right','dressing quietly','object','isolated']],['temperature','smell','sound','touch','sight'],['coals settling','sleep breathing','water under pilings'],'warm-observational')},
's1-hearth':{id:'s1-hearth',sceneId:'smoke-before-daylight',kicker:'The first food',title:'What the Fire Keeps',pressure:'Food, information, and company are briefly in the same place.',body:`<p>Eda crouched beside the coals with one sleeve tied above the elbow. She did not ask why Kalos was awake. She moved three pieces of crisp skin from the warming stone: one large, two small.</p><p>Veya and an unfamiliar man were speaking near the doorway. The man said the outer racks had been left too long in fog. Veya answered that a person who wanted help should arrive before the food was divided.</p><p>Seli looked at the largest piece. Then she looked away from it.</p>`,choicePrompt:'The household is waking.',choiceHint:'Pleasure, knowledge, and affiliation need not point in the same direction.',choices:[C('take-skin','Take the largest piece before anyone assigns it','Eat while it is still hot enough to blister the tongue.','standard',['appetite','visible']),C('split-with-pali','Break the large piece for Pali','Wake the younger child with food rather than cold.','standard',['care','visible']),C('ask-about-fog','Ask what happened to the outer racks','Risk being sent away from an adult conversation.','standard',['curiosity','public']),C('save-for-seli','Leave the large piece beside Seli’s belt','Do not say it is for her.','standard',['private','cost now'])],freeText:true,visual:V('longhouse','What the Fire Keeps','Food before assignment.','ember-smoke','medium','low-cloud','falling','orange coals on faces, blue doorway beyond',['oil tightening on hot skin','people rising behind the fire'],['three pieces of crisp skin','Eda’s tied sleeve','fog at the doorway'],[['eda','center','crouched at the coals','object','crowded'],['seli','foreground-right','standing ready to leave','object','near'],['veya','background-left','speaking quietly with a visitor','away','near']],['taste','smell','temperature','sound','sight'],['fat ticking on stone','low adult voices','someone coughing awake'],'warm-observational')},
's1-road':{id:'s1-road',sceneId:'smoke-before-daylight',kicker:'The path to the drying yard',title:'Who Walks Beside Him',pressure:'Every person has acquired a direction.',body:`<p>By the time the inlet turned gray, every person had acquired a direction.</p><p>Mara went ahead with the hook tray under one arm. Neri carried a bowl of wet fiber with both hands. Oren dragged an unfinished line basket and stopped whenever someone important might notice him carrying it. Seli had Pali at her side despite every effort to avoid exactly that.</p><p>Kalos could reach any of them before the path narrowed.</p>`,choicePrompt:'Whose morning does he enter?',choiceHint:'Proximity creates knowledge before it creates loyalty.',choices:[C('walk-mara','Catch Mara','Ask what work she trusts an eight-year-old to do.','light'),C('walk-neri','Take one side of Neri’s fiber bowl','Make the carrying easier without calling it help.','light'),C('walk-oren','Fall in beside Oren','Hear what the older children plan after work.','light'),C('walk-seli','Take Pali from Seli','Give his sister the unclaimed part of the path.','light')],freeText:false,visual:V('inlet','Who Walks Beside Him','Long Roof to the drying yard.','salt-daylight','wide','mist','falling','flat dawn opening over mud and water',['children overtaking adults','mist moving between rack poles'],['fiber bowl','unfinished basket','hook tray'],[['mara','background-left','walking steadily with the tray','away','isolated'],['neri','center','carrying a bowl carefully','object','near'],['oren','foreground-right','dragging a basket when watched','kalos','near']],['balance','sound','temperature','sight'],['mud releasing feet','fiber bowl water','distant gulls'],'warm-observational')},
's2-lesson':{id:'s2-lesson',sceneId:'the-drying-racks',kicker:'Morning work',title:'Six Turns',pressure:'Mara expects reliable work, not promising imitation.',body:`<p>Mara showed the binding once with ordinary hands and once slowly enough to make the slowness an accusation.</p><div class="dialogue"><span class="speaker">Mara</span>“Six turns. Each one beside the last. Bone does not forgive a space because you were nearly careful.”</div><p>Neri’s first hook sat clean in his palm. Oren had found a reason to carry his basket past the adults twice.</p>`,choicePrompt:'How does Kalos learn the work?',choiceHint:'Technique can be borrowed, requested, displayed, or reinvented.',choices:[C('ask-repeat','Ask Mara to show the knot again','Accept looking younger in exchange for certainty.','standard',['public','precision']),C('copy-neri','Watch Neri’s thumbs','Learn without putting him in the role of teacher.','standard',['private','observation']),C('race-work','Try to finish before Neri','Use speed to make skill visible.','standard',['status','risk']),C('invent-method','Change the wrap so the cord crosses only once','A faster method may hold—or merely look clever.','standard',['novelty','uncertain'])],freeText:true,visual:V('drying-racks','Six Turns','Mara’s work mat.','salt-daylight','close','low-cloud','low','hardening daylight through rows of fish',['fiber twisting in wet fingers','fish bodies moving in wind'],['bone hook','six wet turns','Neri’s thumbs'],[['mara','foreground-left','hands extended over the work mat','object','near'],['neri','center','sitting squarely with a finished hook','object','near'],['kalos','foreground-right','leaning toward the work','object','crowded']],['touch','sight','smell','sound'],['cord drawn against bone','racks creaking','knives on cleaning stones'],'technical')},
's2-interruption':{id:'s2-interruption',sceneId:'the-drying-racks',kicker:'The yard moves around the work',title:'The Bowl Tips',pressure:'The accident lasts only a breath.',body:`<p>Pali arrived without Seli and with the confidence of a child who had escaped someone.</p><p>He caught one heel on the work mat. The bowl of prepared fiber tilted. Neri trapped it against his knee, but half the water went dark across Mara’s hooks.</p><p>Oren laughed before he knew whether Mara would.</p>`,choicePrompt:'Kalos cannot save every object and every person.',choiceHint:'What he reaches for becomes visible before any explanation.',choices:[C('catch-pali','Catch Pali before he falls into the rack','Let the fiber bowl finish tipping.','light'),C('save-hooks','Snatch the hook tray clear','Leave Neri to hold the bowl and Pali to find his feet.','light'),C('make-pali-laugh','Turn the stumble into a game','Keep Pali from crying while adults recover the work.','light'),C('blame-seli','Ask loudly where Seli is','Move the accident toward the person assigned to watch him.','light')],freeText:true,visual:V('drying-racks','The Bowl Tips','A small accident in a busy yard.','salt-daylight','split','low-cloud','low','white daylight flashing on spilled water',['bowl turning','fiber sliding','Pali’s arms windmilling'],['spilled fiber','hook tray','Pali’s bare heel'],[['pali','center','falling sideways','kalos','crowded'],['neri','foreground-left','pinning the bowl against his knee','object','crowded'],['oren','background-right','laughing before checking Mara','mara','isolated']],['balance','touch','sound','sight'],['water striking the mat','one sharp laugh','Pali drawing breath'],'technical')},
's2-assignment':{id:'s2-assignment',sceneId:'the-drying-racks',kicker:'Before the beach',title:'Eight Hooks',pressure:'Sunset has entered the assignment.',body:`<p>Near midday Mara set eight cleaned hooks on a separate tray.</p><div class="dialogue"><span class="speaker">Mara</span>“These are yours. Finish before sunset. Do not say they are finished because you have become tired of them.”</div><p>Oren, passing with his basket, widened his eyes at Kalos in a perfect imitation of Mara. Neri looked down so she would not see him smile.</p>`,choicePrompt:'How does Kalos receive the assignment?',choiceHint:'A promise can be made aloud, implied, shared, or softened.',choices:[C('promise-eight','“All eight.”','Give Mara a clean promise she can remember.','standard',['public','obligation']),C('ask-neri-pair','Ask whether Neri can work beside him','Trade some independence for shared attention.','standard',['cooperation','visible']),C('joke-about-tired','Ask whether hooks can become tired of children','Make the warning easier to carry without refusing it.','standard',['humor','public']),C('say-nothing','Gather the tray without answering','Accept the work while leaving the promise unnamed.','standard',['private','ambiguous'])],freeText:false,visual:V('drying-racks','Eight Hooks','An assignment with a sunset inside it.','salt-daylight','medium','low-cloud','rising','midday beginning to warm the cedar',['shadows shortening','flies lifting from the racks'],['eight bone hooks','separate tray','Oren’s unfinished basket'],[['mara','foreground-left','placing the tray between them','kalos','near'],['kalos','center','hands ready for the tray','object','near'],['neri','background-right','hiding a smile over his own work','object','isolated']],['sight','touch','temperature','sound'],['hooks touching wood','flies','water returning under the racks'],'technical')},
's3-call':{id:'s3-call',sceneId:'race-beneath-the-fish',kicker:'Late afternoon',title:'The Race Beneath the Fish',pressure:'Seven hooks are finished. The first race will not wait.',body:`<p>Seven hooks sat in the tray.</p><p>The eighth lay between Kalos’s knees while Oren called from the far end of the racks. The older children had invented a race that required touching the black post, passing beneath the hanging fish, and reaching the beach without being struck by a tail.</p><p>Neri had finished his own work. He stayed near enough to be asked and far enough not to ask himself.</p>`,choicePrompt:'The race will begin without him.',choiceHint:'This choice establishes the condition in which the eighth hook is finished—or not.',choices:[C('finish-before-race','Finish the eighth hook before standing','Lose the first race and test whether the laughter survives without him.','hinge',['prevention','cost now']),C('ask-neri-finish','Ask Neri to finish the last binding','Create a shared task whose ownership may later become unclear.','hinge',['private','dependence']),C('hurry-eighth','Give the fiber two hard turns and pull once','Make the work look complete before running.','hinge',['conceal','risk later']),C('leave-openly','Leave the eighth hook plainly unfinished','Go without claiming the tray is complete.','hinge',['visible','unfinished'])],freeText:true,visual:V('hook-close','The Race Beneath the Fish','Seven finished; one calling for time.','bone-fiber','close','clear-cold','rising','late sun passing in bars through the racks',['hanging fish turning','children running beyond the mat'],['eighth hook','two loose turns','black race post'],[['kalos','foreground-left','kneeling over the last hook','oren','isolated'],['neri','background-left','finished but waiting','kalos','near'],['oren','background-right','calling from beneath the racks','kalos','isolated']],['touch','sound','sight','temperature'],['children calling','fiber tightening','fish tails tapping in wind'],'narrowing')},
's3-race':{id:'s3-race',sceneId:'race-beneath-the-fish',kicker:'The work is behind him',title:'Under the Racks',pressure:'Oren has changed the rule after Neri agreed to the race.',body:`<p>Oren changed the rule after Kalos joined. The black post still counted, but now a runner had to cross the wet beam above the drainage cut.</p><p>Neri said the beam had not been part of the race when he agreed to it.</p><div class="dialogue"><span class="speaker">Oren</span>“Then do not agree to the next part.”</div><p>The other children watched Kalos to learn whether the change was clever, cowardly, or merely funny.</p>`,choicePrompt:'How does Kalos enter the game?',choiceHint:'Play makes rank visible because everyone can pretend it does not matter.',choices:[C('take-wet-beam','Take the wet beam first','Use balance and nerve to make the rule belong to him.','standard',['risk','status']),C('rewrite-rule','Add a rule Oren must obey too','Make the game fairer without naming fairness.','standard',['humor','coalition']),C('run-old-course','Run the course they agreed to','Refuse Oren’s change by acting as if it never happened.','standard',['defiance','public']),C('stay-with-neri','Tell Neri the race can leave without both of them','Trade the crowd for one person’s company.','standard',['private','cost now'])],freeText:true,visual:V('race','Under the Racks','Wet beam, black post, beach beyond.','wind-shadow','wide','clear-cold','rising','gold sun broken by hanging fish',['children sprinting between poles','wet beam trembling','shadows flickering'],['wet beam','black post','Oren’s raised hand'],[['oren','foreground-right','claiming the start line','kalos','near'],['neri','foreground-left','standing outside the new rule','kalos','isolated'],['kalos','center','balanced between the two','object','crowded']],['balance','sound','temperature','sight'],['bare feet on cedar','children shouting','water under the beam'],'playful-fast')},
's3-laugh':{id:'s3-laugh',sceneId:'race-beneath-the-fish',kicker:'After the finish',title:'Where the Laugh Lands',pressure:'The first laugh was surprise. The second asks permission.',body:`<p>Neri slipped only once. The mud caught him to both knees and kept his hands clean, which made the fall look deliberate until Oren copied the sound he had made.</p><p>The first laugh belonged to surprise. The second belonged to permission.</p><p>Kalos knew how to move it. He could feel the room inside the space beneath the racks.</p>`,choicePrompt:'What does he do with the laugh?',choiceHint:'Humor can widen a circle, move its target, or make cruelty easier to deny.',choices:[C('laugh-with-neri','Give Neri the better version of the fall','Make him the author of the joke rather than its object.','standard',['humor','repair']),C('turn-on-oren','Imitate Oren checking who is allowed to laugh','Expose the status play beneath the game.','standard',['public','counterattack']),C('let-oren-have-it','Laugh and say nothing more','Keep his place among the older children.','standard',['status','cost elsewhere']),C('help-neri-up','Offer a muddy hand without a joke','Let the silence say something humor cannot.','standard',['private','direct'])],freeText:true,visual:V('race','Where the Laugh Lands','The race is over; the ranking is not.','wind-shadow','medium','clear-cold','high','warm light on wet mud, colder shadow under racks',['mud sliding from Neri’s knees','faces turning toward Kalos'],['Neri’s clean hands','Oren’s copied expression','Kalos’s offered hand'],[['neri','center','kneeling in mud','kalos','isolated'],['oren','foreground-right','performing Neri’s fall','group','crowded'],['kalos','foreground-left','standing where everyone can hear him','neri','near']],['sound','sight','touch','smell'],['laughter separating into voices','mud releasing knees','racks creaking'],'playful-fast')},
's4-return':{id:'s4-return',sceneId:'the-eighth-hook',kicker:'Near sunset',title:'The Eighth Hook',pressure:'The work and the account of the work are now separate things.',body:`<p>The light had moved past the work mat when Kalos returned.</p><p>Seven hooks lay where he had left them. The eighth kept whatever condition he had given it: careful, shared, hurried, or openly incomplete.</p><div class="dialogue"><span class="speaker">Mara, from the cleaning stones</span>“All eight?”</div><p>The older children were still near enough to hear the answer.</p>`,choicePrompt:'What does Kalos say?',choiceHint:'An answer can report the object, manage the audience, or buy time.',choices:[C('report-exactly','Tell Mara exactly what condition the hook is in','Name his own work, Neri’s help, or the unfinished task without improving the account.','hinge',['reveal','public']),C('claim-finished','“All eight.”','Give the household a completed answer whether or not the object supports it.','hinge',['conceal','public']),C('check-before-answer','Walk back to the tray before answering','Let the older children hear the delay.','hinge',['inspect','cost now']),C('answer-with-joke','Ask whether Mara is counting hooks or promises','Change the temperature without yet changing the facts.','hinge',['humor','delay'])],freeText:true,visual:V('hook-close','The Eighth Hook','Near sunset · the account begins.','bone-fiber','close','clear-cold','high','last warm light on bone, yard already blue',['cord end moving in wind','older children slowing to listen'],['eighth hook','Mara’s turned back','the separate tray'],[['kalos','foreground-left','standing between tray and shore','mara','isolated'],['mara','background-right','working without turning','object','isolated'],['oren','background-left','lingering within earshot','kalos','near']],['touch','sound','sight','temperature'],['knife on stone','cord end tapping wood','children pretending not to listen'],'narrowing')},
's4-morning-clear':{id:'s4-morning-clear',sceneId:'the-eighth-hook',kicker:'The next morning',title:'The Hook Holds',pressure:'Nothing has gone wrong, and therefore no one needs a hero.',body:`<p>Mara tested the eighth hook by wrapping the line around both hands and pulling until the cord sang.</p><p>It held.</p><p>No one praised the absence of failure. The fishing party received a complete tray and began arguing about tide. Kalos had lost the first race. He had not acquired a story.</p><p>Neri touched the binding with one thumb and looked at him once.</p>`,choicePrompt:'What does quiet success mean to him?',choiceHint:'Prevention may be inhabited, advertised, shared, or converted into advantage.',choices:[C('keep-quiet-success','Let the hook leave without a claim','Return to ordinary work while no one is watching.','standard',['unperformed','quiet']),C('tell-mara-cost','Tell Mara he missed the race to finish it','Ask the adult world to recognize the cost of prevention.','standard',['public','credit']),C('credit-neri','Say Neri showed him the better turn','Make shared work visible if there was any to share.','standard',['credit','relationship']),C('tease-oren','Ask Oren whether the basket held as well','Convert quiet competence into social advantage.','standard',['humor','status'])],freeText:true,visual:V('drying-racks','The Hook Holds','A morning without accusation.','salt-daylight','medium','mist','falling','clear gray morning on a complete tray',['canoe nudging stones','line drawn taut between Mara’s hands'],['intact eighth hook','complete tray','Oren’s basket'],[['mara','center','testing the line with both hands','object','near'],['kalos','foreground-left','watching without being needed','object','near'],['neri','foreground-right','touching the binding after the test','kalos','near']],['sound','touch','sight','temperature'],['cord singing under strain','canoe against stones','adult tide argument'],'quiet-aftermath')},
's4-accusation':{id:'s4-accusation',sceneId:'the-eighth-hook',kicker:'The next morning',title:'The Hidden Hook',pressure:'The tide is leaving. Someone will stay behind.',body:`<p>The hook lay in Kalos’s palm with a small twist in it, as though the bone had tried to turn away from what had happened.</p><p>The wrapping had slipped down the shank. Two turns crossed where six should have lain flat.</p><p>Mara stood over Neri. Oren said Neri had carried the tray crooked. The fishing party waited with the bad patience of adults losing tide.</p><div class="dialogue"><span class="speaker">Mara</span>“Neri will stay and rebind it unless someone has something useful to say.”</div><p>Neri looked at Kalos. Not pleading. That would have been easier. Only looking.</p>`,choicePrompt:'What does Kalos change?',choiceHint:'Truth, blame, repair, and reputation can move separately.',choices:[C('confess-hook','Put the hook down and own the binding','Clear Neri publicly and accept the morning’s cost.','hinge',['public','reveal','cost now']),C('test-hooks','Ask Mara to test the rest of the tray','Let workmanship approach the truth before Kalos does.','hinge',['public','evidence','delay']),C('joke-oren-basket','Use Oren’s unfinished basket against him','Break the accusation’s authority without necessarily clearing Neri.','hinge',['public','conceal','status']),C('silent-hook','Lower his eyes and let Mara decide','Keep the fishing morning and allow the burden to move.','hinge',['private','conceal','cost later'])],freeText:true,visual:V('hook-close','The Hidden Hook','Early morning · the tide is leaving.','bone-fiber','split','mist','falling','gray morning with one warm shed lamp',['canoe tapping stones','wet lines moving in light wind'],['failed binding','Mara’s open hand','empty path to the canoe'],[['kalos','foreground-left','still shoulders, warm hook-print in palm','neri','near'],['neri','center','standing under accusation without pleading','kalos','isolated'],['oren','foreground-right','leaning forward too eagerly','mara','crowded']],['touch','sound','sight','temperature'],['canoe knock','gull at cleaning stones','Neri’s shortened breath'],'narrowing')},
's5-mara':{id:'s5-mara',sceneId:'the-work-nobody-saw',kicker:'After the canoe leaves',title:'The Work Shed',pressure:'The desirable morning has gone; the work has not.',body:`<p>The adults did not praise Kalos for telling them which child had spoiled the hook. They left without him.</p><p>Mara set six fresh hooks between them in the work shed. Wet cedar, old oil, and the sweet beginning of rot lived beneath the floorboards.</p><div class="dialogue"><span class="speaker">Mara</span>“You wanted to go when they called.”</div><p>Outside, the children found a laugh he could not hear clearly enough to improve.</p>`,choicePrompt:'Mara waits for an answer.',choiceHint:'Explanation may reveal motive, protect self-image, or make shame survivable.',choices:[C('plain-want','“I wanted to go.”','Give the motive without improving it.','standard',['plain','ownership']),C('thought-held','“I thought it would hold.”','Defend the judgment rather than the lie.','standard',['partial','technical']),C('feared-left','“They would have left me.”','Name the social fear beneath the work.','standard',['vulnerable','direct']),C('fish-joke','“It held until a fish asked it to work.”','Use precision and laughter to remain in the room.','standard',['humor','shame'])],freeText:true,visual:V('work-shed','The Work Shed','The desirable morning has gone.','empty-tide','medium','mist','falling','one lamp over the work mat',['lamp flame responding to cracks','fiber straightening between Mara’s fingers'],['six fresh hooks','empty doorway','Mara’s work knife'],[['mara','foreground-right','seated opposite with fiber separated','kalos','near'],['kalos','foreground-left','sitting where the canoe used to be visible','object','near']],['smell','touch','sound','sight'],['fiber against bone','distant children','water leaving beneath floor'],'quiet-aftermath')},
's5-evidence':{id:'s5-evidence',sceneId:'the-work-nobody-saw',kicker:'The testing mat',title:'What the Hands Know',pressure:'Evidence has narrowed the room.',body:`<p>Mara pulled each hook against the heel of her hand.</p><p>The first held. The second held. On the third, the fiber shifted. On the fourth, it moved enough for everyone to see.</p><div class="dialogue"><span class="speaker">Mara</span>“These were not dropped.”</div><p>Neri looked at Kalos. Suspicion did not arrive all at once. It found a place to stand.</p>`,choicePrompt:'What does Kalos add to the evidence?',choiceHint:'He may complete the truth, divide it, weaponize a true fact, or let Mara finish it.',choices:[C('complete-truth','Tell the whole sequence now','Name the hurried work and the false report.','standard',['reveal','delayed']),C('admit-hurried','Admit poor work but not the prior claim','Clear Neri while preserving part of the concealment.','standard',['partial','protect']),C('implicate-lesson','Say Neri showed him the method','Place the failed work inside a true but misleading fact.','standard',['deceptive','shared blame']),C('let-mara-infer','Say nothing more','Allow Mara to reconstruct what Kalos will not state.','standard',['silent','evidence'])],freeText:true,visual:V('hook-close','What the Hands Know','Evidence before confession.','bone-fiber','close','mist','falling','flat light over hands and fiber',['binding shifting beneath Mara’s thumb','Neri’s breath changing'],['third hook','fourth hook','Mara’s testing hand'],[['mara','center','pulling the binding against her palm','object','crowded'],['neri','foreground-right','watching Kalos instead of the hook','kalos','near'],['kalos','foreground-left','waiting while evidence speaks','object','near']],['touch','sight','sound'],['fiber slipping','canoe crew shifting impatiently','no laughter'],'technical')},
's5-neri':{id:'s5-neri',sceneId:'the-work-nobody-saw',kicker:'Behind the shed',title:'What Neri Knows',pressure:'Private repair, public truth, and silence are now different debts.',body:`<p>Kalos found Neri after the canoe had gone.</p><p>The older boy had separated the wet fiber from the dry and laid each strand beside his knee. From the beach came the children’s voices. Oren was telling the basket joke and putting the laugh in the wrong place.</p><div class="dialogue"><span class="speaker">Neri</span>“You tied it.”</div><p>It was not a question.</p>`,choicePrompt:'There is no room to manage but this one.',choiceHint:'What Kalos does here may change the burden without changing the public story.',choices:[C('late-public-confession','“Yes. Come with me. I’ll tell Mara.”','Return after the first failure to return.','hinge',['public','reversal']),C('buy-silence','“I’ll finish it if you keep quiet.”','Exchange labor for control of the account.','hinge',['private','transaction']),C('silent-repair','Sit beside him and take the hook','Reduce the burden while preserving the public lie.','hinge',['private','repair']),C('deny-to-neri','“No. You carried the tray.”','Look at the person paying and preserve the claim.','hinge',['deceptive','direct']),C('leave-for-beach','Go before the older children stop calling','Take the immediate reward and let the story harden.','hinge',['status','cost later'])],freeText:true,visual:V('work-shed','What Neri Knows','Behind the shed after departure.','empty-tide','medium','mist','falling','cool daylight outside, narrow warm line from the shed',['fiber laid into straight rows','children moving beyond sight'],['damaged hook','sorted fiber','Kalos’s marked fingers'],[['neri','center','working without looking up','object','isolated'],['kalos','foreground-left','standing where Neri can see his feet','neri','near']],['sound','touch','sight','smell'],['older children on the beach','fiber drawn straight','one gull on the roof'],'quiet-aftermath')},
's5-prevention':{id:'s5-prevention',sceneId:'the-work-nobody-saw',kicker:'The work no one praises',title:'Ordinary Morning',pressure:'A failure was prevented and therefore cannot be repaired heroically.',body:`<p>The fishing party left with eight hooks.</p><p>Kalos remained in the yard because Mara had already found him another task. There was no rescue, no accusation, and no reason for the adults to repeat his name.</p><p>Neri sat beside him splitting fiber. Oren’s basket failed at one corner and had to be opened again.</p><p>The morning was good. It was not a story.</p>`,choicePrompt:'What does Kalos do with a success no one celebrates?',choiceHint:'Quiet competence can be inhabited, advertised, shared, or converted into advantage.',choices:[C('continue-ordinary','Begin the next hook','Let prevention remain ordinary work.','standard',['quiet','follow-through']),C('seek-mara-credit','Ask Mara whether she saw the eighth binding','Make the invisible cost visible to the person who assigned it.','standard',['credit','public']),C('help-oren-basket','Show Oren where his basket opened','Offer useful knowledge without demanding the laugh.','standard',['repair','rivalry']),C('share-with-neri','Give Neri first choice of the dry fiber','Mark shared work through material rather than speech.','standard',['private','relationship'])],freeText:true,visual:V('drying-racks','Ordinary Morning','A failure prevented and therefore unseen.','salt-daylight','wide','mist','falling','morning widening over an ordinary yard',['canoe leaving','new fiber being split','Oren reopening his basket'],['complete hook tray','fresh fiber','opened basket corner'],[['kalos','foreground-left','already beginning another task','object','near'],['neri','center','splitting fiber beside him','object','near'],['oren','background-right','opening failed basket work','object','isolated']],['touch','sound','temperature','sight'],['canoe pushing off','fiber splitting','ordinary work voices'],'quiet-aftermath')},
's6-close':{id:'s6-close',sceneId:'season-close',kicker:'Several weeks later',title:'When the Fire Burns Low',pressure:'The incident is over. Its meanings continue to diverge.',body:`<p>The first long rain came at night and stayed for three days.</p><p>People moved their sleeping places away from the roof seams. Pali developed a cough that sounded worse after the fire burned low. Oren learned a version of the hook story in which he had known the truth from the beginning.</p><p>Near the coals, Kalos listened to Veya tell an older story badly enough that everyone else had room to remember it differently.</p><p>The eighth hook had left the household. What remained was work, and the account of work, and the people who no longer held the same account.</p>`,choicePrompt:'The season continues beyond this prototype.',choiceHint:'Only state with genuine future leverage crosses into the next phase.',choices:[],freeText:false,visual:V('longhouse','When the Fire Burns Low','First long rain.','low-fire','wide','light-rain','high','low fire and rain-dark doorway',['rain at roof seams','people shifting bedding','smoke pressed downward'],['banked coals','moved bedding','one hook-shaped shadow'],[['kalos','foreground-left','listening beside the low fire','veya','crowded'],['veya','center','telling a story with both hands still','group','crowded'],['pali','foreground-right','sleeping near Eda with a cough','away','touching']],['sound','temperature','smell','touch','sight'],['rain on cedar','Pali coughing','Veya’s low voice'],'quiet-aftermath')}
};
export const BEAT_IDS=new Set(Object.keys(BEATS));
